-- =====================================================================
-- 사찰별 유의사항(TEMPLE.special_notice) / 환불 규정(TEMPLE.refund_policy) 채우기
-- 01-buddhist-site-schema.sql로 TEMPLE 시드까지 실행한 뒤 이 파일을 실행하세요.
--
-- 값 출처:
--  - 프로그램 소개글 안에 환불/유의사항 관련 문장이 들어있는 사찰은 그 문장을 그대로 사용.
--  - 그 외(프로그램 소개글에 해당 문장이 없거나 프로그램 자체가 없는 사찰)는 공통 기본값을 사용 -
--    환불 규정은 TempleStayReservationService.canceledMyReservation()이 실제로 강제하는
--    "체크인 24시간 전까지만 취소 가능" 규칙 그대로, 유의사항은 여러 사찰 소개글에 공통으로
--    반복되는 일반 템플스테이 준수사항.
-- =====================================================================

UPDATE TEMPLE SET special_notice = '임산부는 참여를 금 합니다. 반려동물과 동반 참가는 불가 합니다. 컵라면, 또는 간식은 절대 지참 하시면 안됩니다.', refund_policy = '예약완료 이후, 날짜 변경은 1회 가능하며, 날짜 변경 후 취소 시 환불 불가합니다 예약 후 3일 이내에 입금이 이루어지지 않을시에는 자동취소 됩니다. 참가자격은 다음사람에게 넘어갑니다. 이점을 양지 해 주시기 바랍니다.' WHERE name = '감산사';
UPDATE TEMPLE SET special_notice = '사찰 내에서는 정숙을 유지해 주시고, 예불·공양 등 정해진 프로그램 일정에 맞춰 참여해 주세요. 임산부와 반려동물 동반은 제한되며, 컵라면 등 개인 음식물 반입은 삼가주시기 바랍니다.', refund_policy = '체크인 24시간 전까지 취소하시면 전액 환불됩니다. 체크인 24시간 이내에는 환불이 불가합니다.' WHERE name = '갑사';
